{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readSync } from 'node:fs'

// Read all input from stdin
function readInput() {
  const buffer = Buffer.alloc(1024 * 1024)
  const bytesRead = readSync(0, buffer, 0, buffer.length)
  return buffer.toString('utf8', 0, bytesRead)
}

// Parse three documents from input
function parseInput(input) {
  const lines = input.split('\n')
  // Remove empty tail from trailing newline
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const parts = []
  let current = []

  for (const line of lines) {
    if (line === '%%%') {
      parts.push(current)
      current = []
    } else {
      current.push(line)
    }
  }
  parts.push(current)

  if (parts.length !== 3) {
    return null
  }

  return { mine: parts[0], base: parts[1], theirs: parts[2] }
}

// Greedy LCS algorithm as specified
function greedyLCS(side, base) {
  const matches = []
  let sideIdx = 0
  let baseIdx = 0

  while (sideIdx < side.length && baseIdx < base.length) {
    if (side[sideIdx] === base[baseIdx]) {
      matches.push({ side: sideIdx, base: baseIdx })
      sideIdx++
      baseIdx++
    } else {
      // Advance the side with longer remaining sequence
      const sideRemaining = side.length - sideIdx
      const baseRemaining = base.length - baseIdx
      if (sideRemaining > baseRemaining) {
        sideIdx++
      } else if (baseRemaining > sideRemaining) {
        baseIdx++
      } else {
        // Tie: prefer to advance base
        baseIdx++
      }
    }
  }

  return matches
}

// Find changes between a side and base using LCS matches
function findChanges(side, base, matches) {
  const changes = []
  let sideIdx = 0
  let baseIdx = 0

  for (const match of matches) {
    // Add change from current position to match position (if there is a gap)
    if (sideIdx < match.side || baseIdx < match.base) {
      changes.push({
        baseStart: baseIdx,
        baseEnd: match.base,
        sideStart: sideIdx,
        sideEnd: match.side,
      })
    }
    sideIdx = match.side + 1
    baseIdx = match.base + 1
  }

  // Add remaining change after last match
  if (sideIdx < side.length || baseIdx < base.length) {
    changes.push({
      baseStart: baseIdx,
      baseEnd: base.length,
      sideStart: sideIdx,
      sideEnd: side.length,
    })
  }

  return changes
}

// Main merge logic
async function main() {
  const argv = process.argv.slice(2)

  if (argv.length !== 1 || !['merge', 'merge2', 'regions'].includes(argv[0])) {
    process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
    process.exit(2)
  }

  const mode = argv[0]

  const input = readInput()
  const docs = parseInput(input)

  if (!docs) {
    process.stderr.write('error: expected three parts separated by %%%\n')
    process.exit(2)
  }

  const { mine, base, theirs } = docs

  // Find LCS and changes for both sides
  const mineMatches = greedyLCS(mine, base)
  const theirsMatches = greedyLCS(theirs, base)

  const mineChanges = findChanges(mine, base, mineMatches)
  const theirsChanges = findChanges(theirs, base, theirsMatches)

  // Combine all changes and sort by base position
  const allChanges = []
  for (const change of mineChanges) {
    allChanges.push({ ...change, side: 'mine' })
  }
  for (const change of theirsChanges) {
    allChanges.push({ ...change, side: 'theirs' })
  }

  // Sort: first by base start, then mine before theirs
  allChanges.sort((a, b) => {
    if (a.baseStart !== b.baseStart) {
      return a.baseStart - b.baseStart
    }
    return a.side === 'mine' ? -1 : 1
  })

  // Group changes into regions
  const regions = []
  let baseIdx = 0
  let changeIdx = 0

  while (baseIdx < base.length || changeIdx < allChanges.length) {
    if (changeIdx >= allChanges.length) {
      // Stable region to end
      if (baseIdx < base.length) {
        regions.push({
          type: 'stable',
          baseStart: baseIdx,
          baseEnd: base.length,
        })
      }
      break
    }

    const firstChange = allChanges[changeIdx]

    if (firstChange.baseStart > baseIdx) {
      // Stable region before first change
      regions.push({
        type: 'stable',
        baseStart: baseIdx,
        baseEnd: firstChange.baseStart,
      })
      baseIdx = firstChange.baseStart
    }

    // Start a region with this change
    let regionStart = firstChange.baseStart
    let regionEnd = firstChange.baseEnd
    const regionChanges = [firstChange]
    changeIdx++

    // Absorb overlapping changes
    while (
      changeIdx < allChanges.length &&
      allChanges[changeIdx].baseStart <= regionEnd
    ) {
      const change = allChanges[changeIdx]
      regionChanges.push(change)
      regionEnd = Math.max(regionEnd, change.baseEnd)
      changeIdx++
    }

    // Collect lines from all changes in this region
    const mineLines = []
    const theirsLines = []
    const baseLinesSet = new Set()

    for (const change of regionChanges) {
      if (change.side === 'mine') {
        for (let i = change.sideStart; i < change.sideEnd; i++) {
          mineLines.push(mine[i])
        }
      } else {
        for (let i = change.sideStart; i < change.sideEnd; i++) {
          theirsLines.push(theirs[i])
        }
      }
    }

    const baseLines = base.slice(regionStart, regionEnd)

    // Determine region type and resolve
    let resolvedType = null
    let resolvedLines = null

    if (regionChanges.every((c) => c.side === 'mine')) {
      // Only mine changed
      resolvedType = 'mine'
      resolvedLines = mineLines
    } else if (regionChanges.every((c) => c.side === 'theirs')) {
      // Only theirs changed
      resolvedType = 'theirs'
      resolvedLines = theirsLines
    } else {
      // Both sides made changes
      const mineStr = mineLines.join('\n')
      const theirsStr = theirsLines.join('\n')
      const baseStr = baseLines.join('\n')

      if (mineStr === theirsStr) {
        resolvedType = 'both'
        resolvedLines = mineLines
      } else if (mineStr === baseStr) {
        resolvedType = 'theirs'
        resolvedLines = theirsLines
      } else if (theirsStr === baseStr) {
        resolvedType = 'mine'
        resolvedLines = mineLines
      } else {
        resolvedType = 'conflict'
      }
    }

    if (resolvedType === 'conflict') {
      regions.push({
        type: 'conflict',
        mineLines,
        baseLines,
        theirsLines,
      })
    } else {
      regions.push({
        type: resolvedType,
        baseStart: regionStart,
        baseEnd: regionEnd,
        lines: resolvedLines,
      })
    }

    baseIdx = regionEnd
  }

  // Output based on mode
  let hasConflict = false

  if (mode === 'merge' || mode === 'merge2') {
    const outputLines = []
    for (const region of regions) {
      if (region.type === 'conflict') {
        hasConflict = true
        outputLines.push('<<<<<<< mine')
        outputLines.push(...region.mineLines)
        if (mode === 'merge') {
          outputLines.push('||||||| base')
          outputLines.push(...region.baseLines)
        }
        outputLines.push('=======')
        outputLines.push(...region.theirsLines)
        outputLines.push('>>>>>>> theirs')
      } else {
        outputLines.push(...region.lines)
      }
    }
    if (outputLines.length > 0) {
      process.stdout.write(outputLines.map((l) => l + '\n').join(''))
    }
  } else {
    // regions mode
    for (const region of regions) {
      if (region.type === 'conflict') {
        hasConflict = true
        process.stdout.write(
          `conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}\n`,
        )
      } else if (region.type === 'stable') {
        const count = region.baseEnd - region.baseStart
        process.stdout.write(`stable ${count}\n`)
      } else {
        process.stdout.write(`${region.type} ${region.lines.length}\n`)
      }
    }
  }

  process.exit(hasConflict ? 1 : 0)
}

main()
