{"file_path":"src/cli.js","old_string":"// Find changes between a side and base using LCS matches
function findChanges(side, base, matches) {
  const changes = []
  let sideIdx = 0
  let baseIdx = 0

  for (const match of matches) {
    // Add change from current position to match position (if there is a gap)
    if (sideIdx < match.side || baseIdx < match.base) {
      changes.push({
        baseStart: baseIdx,
        baseEnd: match.base,
        sideStart: sideIdx,
        sideEnd: match.side,
      })
    }
    sideIdx = match.side + 1
    baseIdx = match.base + 1
  }

  // Add remaining change after last match
  if (sideIdx < side.length || baseIdx < base.length) {
    changes.push({
      baseStart: baseIdx,
      baseEnd: base.length,
      sideStart: sideIdx,
      sideEnd: side.length,
    })
  }

  return changes
}","new_string":"// Find changes between a side and base using LCS matches
function findChanges(side, base, matches) {
